<script setup>
import { computed } from "vue";
import { useAuthStore } from "../stores/auth";
const props = defineProps({ role: { type: String, default: "teacher" } }); const auth = useAuthStore();
const data = computed(() => auth.profile || (() => { try { return JSON.parse(localStorage.getItem(props.role === 'parent' ? 'parent_data' : 'teacher_data') || '{}'); } catch { return {}; } })());
const name = computed(() => [data.value.first_name, data.value.second_name, data.value.last_name || data.value.surname].filter(Boolean).join(" "));
</script>
<template><div><div class="page-heading"><div><span class="mono-label">{{ role.toUpperCase() }} / PROFILE</span><h1>个人资料</h1><p>查看当前账号的基础身份信息。</p></div></div><section class="surface surface-pad" style="max-width:760px"><div style="display:flex; align-items:center; gap:14px; padding-bottom:20px; border-bottom:1px solid var(--light-line)"><span class="avatar" style="width:54px; height:54px; font-size:20px">{{ (name || 'P').slice(0,1) }}</span><div><h2 style="margin:0; color:inherit; font-size:19px">{{ name || 'ParaKindergarten 用户' }}</h2><small style="display:block; margin-top:4px; color:var(--light-muted)">{{ role === 'parent' ? '家长账号' : '教师账号' }}</small></div></div><div class="form-grid" style="margin-top:20px"><div class="field"><label>姓名</label><input :value="name" readonly /></div><div class="field"><label>邮箱</label><input :value="data.email || '未设置'" readonly /></div><div class="field"><label>电话号码</label><input :value="data.phone_number || '未设置'" readonly /></div><div class="field"><label>性别</label><input :value="data.gender || '未设置'" readonly /></div><div v-if="role === 'teacher'" class="field"><label>教师称呼</label><input :value="data.career_name || '未设置'" readonly /></div></div></section></div></template>
